import {kinds,seedState,emptyState,apply,metrics,detect,forecast,today,dayAdd,parseCSV,csv,validateRecord,restoreBackup,can,capabilities,productivity,VERSION} from './core.mjs';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,mode='sandbox',me={name:'Demo operator',role:'owner'},csrf='',workspaceId='',workspaces=[],route=location.hash.slice(1)||'overview',query='',filter='',busy=false,authMode='login',pageNumber=1;
const nav=[['overview','Command center','◉'],['decisions','Decision queue','◇'],['tasks','Execution board','▤'],['invoices','Receivables','↗'],['deals','Sales pipeline','▥'],['projects','Delivery','▦'],['customers','Customers','◎'],['vendors','Procurement','▱'],['people','Capacity','◷'],['tickets','Service desk','◈'],['scenarios','Scenario lab','⌁'],['outcomes','Outcomes & memory','↺'],['connections','Data & integrations','⇄'],['productivity','Performance','▥'],['admin','Administration','⚙'],['permissions','Authorizations','▦'],['team','Team & access','♙'],['settings','Settings','⚙']];
const labels={customer:'Customer',lastContact:'Last contact',baseline:'Baseline spend',paid:'Amount paid',health:'Health score',renewal:'Renewal date',value:'Account value',allocated:'Allocated hours',capacity:'Available hours',monthlyBurn:'Monthly operating outflow',approvalLimit:'Manager approval limit',cycleMinutes:'Cycle interval (minutes)'};
const label=k=>labels[k]||k.charAt(0).toUpperCase()+k.slice(1),money=n=>new Intl.NumberFormat('en',{style:'currency',currency:state?.company.currency||'SAR',maximumFractionDigits:0}).format(n||0),short=n=>new Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(n||0),badge=s=>`<span class="badge ${esc(s)}">${esc(String(s).replaceAll('_',' '))}</span>`;
const time=v=>v?new Date(v).toLocaleString('en',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'Not run yet';
const btn=(text,action,attrs='',cls='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const empty=(title,description,action='')=>`<div class="empty"><h2>${title}</h2><p>${description}</p>${action}</div>`;
const customer=id=>state.records.customers.find(x=>x.id===id)?.name||'—';
function toast(message){const t=$('#toast');t.textContent=message;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',5500);}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function api(path,body,key){const r=await fetch('/api'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-CSRF-Token':csrf,...(key?{'Idempotency-Key':key}:{})}:{},body:body?JSON.stringify(body):undefined,credentials:'same-origin'});const d=await r.json();if(!r.ok)throw Object.assign(Error(d.error||'Request failed'),{status:r.status});return d;}
function storeSandbox(){const all=JSON.parse(localStorage.getItem('operon.v2.workspaces')||'{}');all[workspaceId]=state;localStorage.setItem('operon.v2.workspaces',JSON.stringify(all));localStorage.setItem('operon.v2.selected',workspaceId);workspaces=Object.entries(all).map(([id,s])=>({id,name:s.company.name,role:'owner'}));}
async function command(c,message='Saved'){
 if(busy)return;busy=true;
 try{if(mode==='server'){const out=await api('/workspaces/'+workspaceId+'/command',{version:state.version,command:c},crypto.randomUUID());state=out.state;}else{const next=apply(state,c,me).state;const old=state;state=next;try{storeSandbox();}catch(e){state=old;throw Error('Browser storage is full or unavailable. Export your workspace before continuing.');}}
 render();if(message)toast(message);return true;
 }catch(e){if(e.status===409&&mode==='server'){await loadWorkspace();render();}throw e;}finally{busy=false;}
}
function head(title,sub,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p class="muted">${sub}</p></div><div class="flex wrap">${actions}</div></div>`;}
function kpi(title,value,note){return `<div class="card"><div class="kpi-label">${title}</div><div class="kpi-value">${value}</div><div class="kpi-note">${note}</div></div>`;}
function decisionRow(d){return `<div class="decision-row"><div class="flex between"><div class="flex">${badge(d.severity)}<small>${esc(d.domain)}</small></div>${badge(d.status)}</div><span class="decision-title">${esc(d.title)}</span><p class="muted">${esc(d.evidence)}</p><div class="flex between wrap"><small>${esc(d.owner)} · ${d.exposure?money(d.exposure)+' exposed':'Operational risk'}</small><div class="flex wrap">${btn('Review decision','decision.open',`data-id="${esc(d.id)}"`,'text-btn')}${d.status==='pending'&&can(state,me.role,'decisions.approve')&&can(state,me.role,'decisions.execute')?btn('Approve & assign','decision.approve_assign',`data-id="${esc(d.id)}"`):''}</div></div></div>`;}
function overview(){const m=metrics(state),pending=state.decisions.filter(d=>d.status==='pending'),open=state.tasks.filter(t=>t.status!=='completed');return head('Command center','Focus on what needs a decision, an owner, or evidence.',btn('Run operating cycle','cycle','','primary'))+
 `<div class="quick-actions"><a href="./welcome.html">Product overview ↗</a>${btn('+ Create task','task.open')}${btn('Performance dashboard','navigate','data-route="productivity"')}<span class="muted">Search records with Ctrl / ⌘ K</span></div><div class="brief card"><div><span class="eyebrow">Operating brief · ${today()}</span><h2>${pending.length?pending.length+' decisions need your attention.':'Your next operating cycle starts here.'}</h2><p>${m.overdue?money(m.overdue)+' in overdue receivables. ':''}${m.atRisk} projects need attention. ${open.length} open actions. Review the evidence, assign the work, and verify the result.</p></div>${btn('Open decision queue →','navigate','data-route="decisions"','dark-btn')}</div>`+
 `<div class="grid kpis">${kpi('Overdue receivables',money(m.overdue),'Derived from outstanding invoice balances')}${kpi('Operating runway',m.runway===null?'—':m.runway+' days','Cash ÷ monthly operating outflow × 30')}${kpi('Weighted pipeline',money(m.weighted),'Open deals × entered probability')}${kpi('Recorded cash outcomes',money(m.verified),'User-attested evidence; not bank reconciled')}</div>`+
 `<div class="grid two-col"><section class="card"><div class="card-head"><h2>Priority decisions</h2><small>${pending.length} awaiting approval</small></div>${pending.slice(0,5).map(decisionRow).join('')||empty('No pending decisions','Add your business records and run a cycle to identify exceptions.',btn('Add records','navigate','data-route="connections"'))}</section><div class="grid"><section class="card"><div class="card-head"><h2>Business coverage</h2><small>7 domains</small></div>${Object.entries(kinds).map(([k,v])=>{const n=state.decisions.filter(d=>d.kind===k&&['pending','approved','executing','awaiting_verification'].includes(d.status)).length;return `<div class="health-row"><div class="flex between"><span>${v.label}</span><small>${n} open · ${state.records[k].length} records</small></div><div class="mini-bar"><span style="width:${state.records[k].length?Math.max(10,100-n/Math.max(1,state.records[k].length)*100):0}%"></span></div></div>`;}).join('')}<small>Bars show records without an open exception, not an AI confidence score.</small></section><section class="card"><h2>Recent activity</h2>${state.audit.slice(0,5).map(a=>`<div class="activity">${esc(a.action)}<small>${esc(a.actor)} · ${time(a.at)}</small></div>`).join('')||'<p class="muted">Your audit history will appear here.</p>'}</section></div></div>`;}
function pager(total){const pages=Math.max(1,Math.ceil(total/50));pageNumber=Math.min(pageNumber,pages);return `<div class="toolbar subsection"><small>${total} results · Page ${pageNumber} of ${pages} · Up to 50 per page</small><div class="flex">${btn('Previous','page',`data-page="${pageNumber-1}" ${pageNumber===1?'disabled':''}`)}${btn('Next','page',`data-page="${pageNumber+1}" ${pageNumber===pages?'disabled':''}`)}</div></div>`;}
function decisions(){const ds=state.decisions.filter(d=>(!filter||d.status===filter)&&`${d.title} ${d.owner} ${d.domain}`.toLowerCase().includes(query.toLowerCase()));return head('Decision queue','Evidence-backed recommendations with explicit authority and outcome tracking.',btn('Run operating cycle','cycle','','primary'))+`<div class="toolbar"><input id="filter-search" aria-label="Search decisions" placeholder="Search decisions, owners, domains…" value="${esc(query)}"><select id="status-filter" aria-label="Decision status"><option value="">All statuses</option>${['pending','approved','executing','awaiting_verification','verified','rejected','superseded'].map(s=>`<option value="${s}" ${filter===s?'selected':''}>${label(s.replaceAll('_',' '))}</option>`).join('')}</select></div>`+(ds.length?`<div class="grid three-col">${ds.slice((pageNumber-1)*50,pageNumber*50).map(d=>`<section class="card">${decisionRow(d)}</section>`).join('')}</div>`:empty('No matching decisions','Try a different filter or run an operating cycle after adding records.'))+pager(ds.length);}
const tableColumns={invoices:['name','customer','amount','paid','due','status'],deals:['name','customer','amount','probability','lastContact','status'],projects:['name','customer','budget','cost','progress','due','status'],customers:['name','owner','value','health','renewal','status'],vendors:['name','spend','baseline','due','status'],people:['name','team','capacity','allocated','status'],tickets:['name','customer','owner','priority','due','status']};
function formatCell(k,v,type){if(k==='customer')return esc(customer(v));if(['status','priority'].includes(k))return badge(v);if(type==='money')return money(v);if(type==='percent')return esc(v)+'%';return esc(v);}
function recordsView(kind){const def=kinds[kind],rows=state.records[kind].filter(r=>Object.values(r).some(v=>String(v).toLowerCase().includes(query.toLowerCase()))),cols=tableColumns[kind];return head(def.label,`${state.records[kind].length} business records · ${def.domain} operations`,btn('Export CSV','records.export',`data-kind="${kind}"`)+btn('+ Add record','record.open',`data-kind="${kind}"`,'primary'))+`<div class="toolbar"><input id="filter-search" aria-label="Search records" placeholder="Search ${def.label.toLowerCase()}…" value="${esc(query)}">${btn('Import records','import.open',`data-kind="${kind}"`)}</div>`+(rows.length?`<div class="table-wrap"><table><thead><tr>${cols.map(k=>`<th>${label(k)}</th>`).join('')}<th>Action</th></tr></thead><tbody>${rows.slice((pageNumber-1)*50,pageNumber*50).map(r=>`<tr>${cols.map(k=>`<td>${formatCell(k,r[k],def.fields[k])}${k==='name'?`<div class="cell-sub">${esc(r.owner||'Unassigned')}</div>`:''}</td>`).join('')}<td>${btn('Open','record.open',`data-kind="${kind}" data-id="${esc(r.id)}"`,'text-btn')}</td></tr>`).join('')}</tbody></table></div>`:empty('No records to show','Create a record or import a CSV file to start managing this part of your business.',btn('Add first record','record.open',`data-kind="${kind}"`,'primary')))+pager(rows.length);}
function tasksView(){return head('Execution board','Every approved decision becomes owned work. Completion requires a separate outcome review.',btn('+ Create task','task.open','','primary'))+`<div class="tabs">${[['','All work'],['mine','My work'],['overdue','Overdue'],['unassigned','Unassigned']].map(([f,l])=>btn(l,'task.filter',`data-filter="${f}"`,filter===f?'active':'')).join('')}</div><div class="kanban">${['todo','in_progress','blocked','completed'].map(status=>{const ts=state.tasks.filter(t=>t.status===status&&(!filter||filter==='mine'&&t.owner===me.name||filter==='overdue'&&t.due<today()&&t.status!=='completed'||filter==='unassigned'&&(!t.owner||t.owner==='Unassigned'))&&`${t.name} ${t.owner}`.toLowerCase().includes(query.toLowerCase()));return `<section class="kanban-col"><div class="kanban-title">${status.replaceAll('_',' ')} <span>${ts.length}</span></div>${ts.map(t=>`<div class="task" role="button" tabindex="0" data-action="task.open" data-id="${t.id}">${badge(t.priority)}<h3>${esc(t.name)}</h3><div class="flex between"><small>${esc(t.owner)}</small><small>${esc(t.due)}</small></div>${t.decisionId?'<small>Linked to decision</small>':''}<div class="flex wrap subsection">${t.status!=='completed'?btn('Complete','task.complete',`data-id="${t.id}"`,'text-btn'):t.decisionId?btn('Review outcome','decision.open',`data-id="${esc(t.decisionId)}"`,'text-btn'):''}</div></div>`).join('')||'<small>No work in this stage</small>'}</section>`;}).join('')}</div>`;}
function scenariosView(){const f=forecast(state);return head('Scenario lab','Test your assumptions without changing business records.')+`<div class="grid two-col"><div class="card"><h2>30-day cash sensitivity</h2><form id="scenario-form">${[['collection','Receivables collected',60,0,100],['winRate','Pipeline converted to bookings',20,0,100],['spendChange','Change in operating outflow',0,-50,100]].map(([name,l,value,min,max])=>`<div class="field"><label class="range-label" for="${name}">${l}<b id="${name}-value">${value}%</b></label><input type="range" id="${name}" name="${name}" min="${min}" max="${max}" value="${value}"></div>`).join('')}</form><div id="scenario-result">${scenarioResult(f)}</div></div><div class="card"><h2>What this model assumes</h2><div class="detail-block"><b>Collections affect cash</b><p>Collection percentage applies to outstanding invoices. It is an assumption, not a collection forecast.</p></div><div class="detail-block"><b>Bookings are separate</b><p>Winning a deal does not immediately put cash in the bank. Pipeline conversion is shown separately.</p></div><div class="detail-block"><b>Operating outflow stays constant</b><p>The monthly amount comes from company settings. This model excludes taxes, financing, seasonality, and payment timing within the month.</p></div>${btn('Edit cash assumptions','navigate','data-route="settings"')}</div></div>`;}
function scenarioResult(f){const max=Math.max(f.opening,f.cashIn,f.burn,Math.abs(f.closing),1);return `<div class="grid" style="grid-template-columns:1fr 1fr"><div><small>Modeled closing cash</small><div class="scenario-value">${money(f.closing)}</div></div><div><small>Modeled new bookings</small><div class="scenario-value">${money(f.bookings)}</div></div></div><div class="chart-bars" role="img" aria-label="Opening cash ${f.opening}, collections ${f.cashIn}, outflow ${f.burn}, closing cash ${f.closing}">${[['Opening',f.opening],['Collections',f.cashIn],['Outflow',f.burn],['Closing',f.closing]].map(([l,v])=>`<div class="chart-bar"><i style="height:${Math.abs(v)/max*125}px"></i>${l}<br>${money(v)}</div>`).join('')}</div>`;}
function outcomesView(){return head('Outcomes & business memory','Trace recorded results back to decisions, evidence, and responsible people.',btn('Export audit','audit.export')+btn('Export workspace','backup'))+`<div class="grid kpis">${kpi('Verified decisions',state.decisions.filter(x=>x.status==='verified').length,'Closed after evidence review')}${kpi('Recorded collections',money(state.outcomes.filter(x=>x.category==='cash_received').reduce((a,x)=>a+x.amount,0)),'User-attested cash receipts')}${kpi('Recorded savings',money(state.outcomes.filter(x=>x.category==='cost_saved').reduce((a,x)=>a+x.amount,0)),'User-attested cost reductions')}${kpi('Operating cycles',state.cycles.length,'Persistent cycle history')}</div><div class="grid two-col"><section class="card"><h2>Outcome ledger</h2>${state.outcomes.length?state.outcomes.slice().reverse().map(o=>`<div class="decision-row">${badge(o.category)}<span class="decision-title">${esc(state.decisions.find(d=>d.id===o.decisionId)?.title)}</span><p>${esc(o.evidence)}</p><div class="flex between"><b>${o.amount?money(o.amount):'Operational result'}</b><small>${esc(o.actor)} · ${time(o.at)}</small></div></div>`).join(''):empty('No verified outcomes yet','Approve a decision, complete its task, and record evidence to build your company’s outcome history.')}</section><section class="card"><h2>Audit trail</h2><div class="timeline">${state.audit.slice(0,50).map(a=>`<div class="activity"><b>${esc(a.action)}</b><p class="muted">${esc(a.detail)}</p><small>${esc(a.actor)} · ${time(a.at)}</small></div>`).join('')}</div></section></div>`;}
function connectionsView(){return head('Data & integrations','Bring your business records into one operating model.')+`<div class="notice">${mode==='sandbox'?'Browser sandbox: data stays in this browser. Use synthetic or non-sensitive data.':'Workspace data is stored in the server database.'} CSV import is available now. Third-party OAuth, messaging, banking, and billing providers are not connected.</div><div class="grid three-col">${Object.entries(kinds).map(([k,v])=>`<section class="card connection-card"><div class="flex between"><div class="connection-icon">${v.label.charAt(0)}</div>${badge('available')}</div><h3>${v.label} import</h3><p>Validate every row before saving. Existing records are matched by name within this workspace.</p><small>${state.records[k].length} records</small><div class="flex wrap subsection">${btn('Import CSV','import.open',`data-kind="${k}"`,'primary')}${btn('Template','template',`data-kind="${k}"`)}</div></section>`).join('')}</div><section class="card subsection"><h2>Recent imports</h2>${state.imports.map(i=>`<div class="metric-line"><span>${kinds[i.kind].label} · ${i.count} records</span><small>${time(i.at)}</small></div>`).join('')||'<p class="muted">No imports yet.</p>'}</section>`;}
function settingsView(){const c=state.company;return head('Company settings','Operating assumptions, approval authority, and workspace controls.')+`<div class="card settings-form"><form id="settings-form"><h2>Company profile</h2><div class="form-grid">${field('name','Company name','text',c.name)}${field('currency','Currency','text',c.currency)}${field('cash','Current operating cash','money',c.cash)}${field('monthlyBurn',label('monthlyBurn'),'money',c.monthlyBurn)}</div><h2 class="subsection">Decision authority</h2><p class="muted">Managers may approve decisions up to the exposure limit. Higher amounts require the owner. Operators manage records and assigned work. Viewers have read-only access.</p>${field('approvalLimit',label('approvalLimit'),'money',c.approvalLimit)}<h2 class="subsection">Operating schedule</h2>${field('cycleMinutes',label('cycleMinutes'),'number',c.cycleMinutes)}<label class="flex"><input name="automation" type="checkbox" ${c.automation?'checked':''}> Run scheduled detection cycles</label><p class="muted" style="font-size:14px">${mode==='server'?'The server checks the schedule every 30 seconds while the service is running.':'In the browser sandbox, scheduled detection runs only while this page is open.'} Cycles detect exceptions; they do not send messages or move money.</p><p class="error" id="form-error"></p><button class="primary" type="submit">Save settings</button></form></div><div class="card settings-form subsection"><h2>Workspace data</h2><div class="flex wrap">${btn('Export workspace JSON','backup')}${mode==='sandbox'?btn('Restore JSON backup','restore.open'):''}${btn('Create workspace','workspace.open')}</div><p class="muted subsection">Application ${VERSION} · Workspace revision ${state.version} · Last cycle ${time(state.lastCycle)}</p></div>`;}
function teamView(){return head('Team & access','Clear responsibilities and workspace boundaries.',mode==='server'?btn('Create invitation','invite.open','','primary'):'')+`<div class="notice">${mode==='sandbox'?'The browser sandbox has one local operator. Authentication and team permissions require the OPERON server.':'Invitations are bound to an email address and expire after seven days. Creating an invitation does not send email.'}</div><div class="card"><h2>Workspace members</h2><div id="members-list"><div class="metric-line"><span>${esc(me.name)}</span>${badge(me.role)}</div></div></div><div class="grid three-col subsection">${[['Owner','Company settings, memberships, all approvals and verification.'],['Manager','Records, tasks, outcomes, and approvals within the configured limit.'],['Operator / viewer','Operators manage records and work. Viewers can inspect and export.']].map(([a,b])=>`<div class="card"><h3>${a}</h3><p class="muted">${b}</p></div>`).join('')}</div>${mode==='server'?`<div class="card subsection"><h2>Your account</h2><div id="session-list">Loading active sessions…</div><div class="subsection">${btn('Sign out other sessions','sessions.others')}</div><div class="flex wrap">${btn('Accept invitation','invite.accept.open')}${btn('Change password','password.open')}</div></div>`:''}`;}
function render(){if(!state)return;const m=metrics(state);document.title='OPERON · '+(nav.find(x=>x[0]===route)?.[1]||'Operations');$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><img src="./favicon.svg" alt="">OPERON</div><div class="workspace-label"><small>WORKSPACE</small><br><button class="text-btn" style="color:white;text-align:left" data-action="workspace.switch">${esc(state.company.name)} ▾</button></div><nav aria-label="Main navigation">${nav.map(([r,n,icon],i)=>`${[0,3,10,12].includes(i)?`<div class="nav-label">${({0:'Operate',3:'Business records',10:'Intelligence',12:'Workspace'})[i]}</div>`:''}<button class="nav-item ${route===r?'active':''}" data-action="navigate" data-route="${r}" ${route===r?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${n}${r==='decisions'&&m.pending?`<span class="nav-count">${m.pending}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><small>Last cycle<br>${time(state.lastCycle)}</small>${mode==='server'?btn('Sign out','logout'):btn('About this sandbox','sandbox.info')}</div></aside><div class="shell"><header class="topbar">${btn('☰','menu','','mobile-menu')}<input class="search" id="global-search" placeholder="Search business records…" aria-label="Search all records"><div class="top-actions"><span class="mode ${mode==='server'?'live':''}">${mode==='server'?'Server workspace':'Interactive sandbox'}</span><span class="user-name">${esc(me.name)}</span><span class="avatar">${esc(me.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span></div></header><main id="main" tabindex="-1">${kinds[route]?recordsView(route):({overview,decisions,tasks:tasksView,scenarios:scenariosView,outcomes:outcomesView,connections:connectionsView,team:teamView,settings:settingsView,productivity:productivityView,admin:adminView,permissions:permissionsView}[route]||overview)()}</main></div></div>`;
 applyUIAuthorizations();if(route==='admin')loadAdmin();if(route==='team')loadSessions();
 if(route==='team'&&mode==='server')api('/workspaces/'+workspaceId+'/members').then(d=>{if($('#members-list'))$('#members-list').innerHTML=d.members.map(m=>`<div class="metric-line"><div>${esc(m.name)}<br><small>${esc(m.email)}</small></div><div class="flex">${badge(m.role)}${me.role==='owner'&&m.role!=='owner'?btn('Manage','member.open',`data-id="${m.id}" data-role="${m.role}"`,'text-btn'):''}</div></div>`).join('');}).catch(e=>toast(e.message));
}
function field(name,title,type,value=''){let control;if(Array.isArray(type))control=`<select name="${name}" id="f-${name}">${type.map(v=>`<option value="${v}" ${v===value?'selected':''}>${label(v.replaceAll('_',' '))}</option>`).join('')}</select>`;else if(type==='textarea')control=`<textarea name="${name}" id="f-${name}">${esc(value)}</textarea>`;else if(type==='customer')control=`<select name="${name}" id="f-${name}"><option value="">No linked customer</option>${state.records.customers.map(c=>`<option value="${c.id}" ${c.id===value?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`;else control=`<input name="${name}" id="f-${name}" type="${['money','number','percent'].includes(type)?'number':type}" value="${esc(value)}" ${['money','number','percent'].includes(type)?`min="0" step="0.01" ${type==='percent'?'max="100"':''}`:''} ${['name','due','lastContact','renewal'].includes(name)?'required':''}>`;return `<div class="field ${type==='textarea'?'full':''}"><label for="f-${name}">${title}</label>${control}</div>`;}
function modal(title,body){const d=$('#dialog');d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2>${btn('✕','close','aria-label="Close dialog"')}</div><div class="dialog-body">${body}</div>`;if(!d.open)d.showModal();applyUIAuthorizations();}
const formEnd=(text='Save')=>`<p id="form-error" class="error" role="alert"></p><div class="dialog-foot">${btn('Cancel','close','type="button"')}<button class="primary" type="submit">${text}</button></div></form>`;
function openRecord(kind,id){const r=state.records[kind].find(x=>x.id===id)||{},defaults=Object.fromEntries(Object.entries(kinds[kind].fields).map(([k,t])=>[k,Array.isArray(t)?t[0]:t==='date'?today():['money','number','percent'].includes(t)?0:'']));modal(`${id?'Edit':'Add'} ${kinds[kind].label.toLowerCase()} record`,`<form id="record-form" data-kind="${kind}" data-id="${id||''}"><div class="form-grid">${Object.entries(kinds[kind].fields).map(([k,t])=>field(k,label(k),t,r[k]??defaults[k])).join('')}</div>${id&&kind==='customers'?btn('View linked business','customer.overview',`type="button" data-id="${id}"`):''}${id&&kind==='invoices'&&r.paid<r.amount?btn('Record payment','payment.open',`type="button" data-id="${id}"`,'primary'):''}${id&&kind==='deals'&&!['won','lost'].includes(r.status)?btn('Win & hand off to delivery','convert.open',`type="button" data-id="${id}"`,'primary'):''}${id?btn('Remove record','record.remove',`type="button" data-kind="${kind}" data-id="${id}"`,'danger'):''}${formEnd()}`);}
function openTask(id){const t=state.tasks.find(x=>x.id===id)||{name:'',owner:me.name,due:dayAdd(today(),2),status:'todo',priority:'medium',notes:''};modal(id?'Work item':'Create task',`<form id="task-form" data-id="${id||''}">${field('name','Action to complete','textarea',t.name)}<div class="form-grid">${field('owner','Owner','text',t.owner)}${field('due','Due date','date',t.due)}${field('status','Status',['todo','in_progress','blocked','completed'],t.status)}${field('priority','Priority',['low','medium','high','critical'],t.priority)}</div>${field('notes','Progress notes','textarea',t.notes)}${t.decisionId?'<p class="muted">Completing this task moves its decision to outcome verification.</p>':''}${formEnd()}`);}
function openDecision(id){const d=state.decisions.find(x=>x.id===id);if(!d)return;const task=state.tasks.find(t=>t.decisionId===id&&t.revision===d.revision);modal(esc(d.title),`<div class="flex between">${badge(d.status)}${badge(d.severity)}</div><div class="detail-block"><span class="eyebrow">Source evidence · ${esc(d.domain)}</span><p>${esc(d.evidence)}</p>${btn('Open source record','record.open',`data-kind="${d.kind}" data-id="${d.sourceId}"`,'text-btn')}</div><div class="form-grid"><div><small>Financial exposure</small><h2>${d.exposure?money(d.exposure):'Not quantified'}</h2></div><div><small>Responsible owner</small><h2>${esc(d.owner)}</h2></div></div><p class="muted">${esc(d.basis)}</p><h3>Recommended action</h3><p>${esc(d.action)}</p><small>Rule: ${esc(d.rule)} · Revision ${d.revision} · No statistical confidence is claimed.</small>${d.reason?`<div class="detail-block">Rejection reason: ${esc(d.reason)}</div>`:''}${task?`<div class="detail-block"><b>Assigned work</b><p>${esc(task.name)}</p>${badge(task.status)} ${btn('Open task','task.open',`data-id="${task.id}"`,'text-btn')}</div>`:''}<div class="dialog-foot wrap">${d.status==='pending'?btn('Reject','decision.reject.open',`data-id="${id}"`,'danger')+btn('Modify','decision.modify.open',`data-id="${id}"`)+btn('Approve','decision.approve',`data-id="${id}"`,'primary'):''}${d.status==='approved'?btn('Assign execution task','decision.execute',`data-id="${id}"`,'primary'):''}${d.status==='awaiting_verification'?btn('Verify outcome','decision.verify.open',`data-id="${id}"`,'primary'):''}${['rejected','verified','superseded'].includes(d.status)?btn('Reopen if signal persists','decision.reopen',`data-id="${id}"`):''}</div><p class="error" id="form-error" role="alert"></p>`);}
function importOpen(kind){modal('Import '+kinds[kind].label.toLowerCase(),`<p>Use the template field names. Customer references use IDs from your customer export. Rows are validated before saving; records with the same name are updated.</p>${btn('Download template','template',`data-kind="${kind}"`)}<form id="import-form" data-kind="${kind}"><div class="field subsection"><label for="csv-file">CSV file</label><input type="file" id="csv-file" accept=".csv,text/csv" required></div><div id="import-preview"></div>${formEnd('Validate & import')}</form>`);}
function authView(){state=null;$('#app').innerHTML=`<div class="auth"><div class="auth-intro"><div class="brand"><img src="./favicon.svg" alt="">OPERON</div><span class="eyebrow" style="color:var(--lime)">Business operations</span><h1>Decisions that turn into completed work.</h1><p>One operating loop across cash, revenue, delivery, customers, and people.</p><div class="auth-flow">01 &nbsp; Observe business signals<br>02 &nbsp; Review and authorize decisions<br>03 &nbsp; Assign and complete the work<br>04 &nbsp; Verify outcomes with evidence</div></div><div class="auth-form"><h2>${authMode==='login'?'Welcome back':'Create your workspace'}</h2><p class="muted">${authMode==='login'?'Sign in to your company’s operating workspace.':'Start with an empty, private company workspace.'}</p><form id="auth-form">${authMode==='register'?field('name','Your name','text')+field('company','Company name','text'):''}${field('email','Email','email')}${field('password','Password (12+ characters)','password')}<p id="form-error" class="error"></p><button type="submit" class="primary">${authMode==='login'?'Sign in':'Create account'}</button></form><div class="subsection">${btn(authMode==='login'?'Create an account':'Already registered? Sign in','auth.toggle','','text-btn')}</div><small>Password recovery by email and email verification are not configured. Keep your credentials securely.</small></div></div>`;}
async function loadWorkspace(){const d=await api('/workspaces/'+workspaceId);state=d.state;me.role=d.role;sessionStorage.setItem('operon.workspace',workspaceId);}
function navigate(r){query='';filter='';pageNumber=1;route=r;location.hash=r;render();window.scrollTo(0,0);}
const actions={
 navigate:e=>navigate(e.dataset.route),menu:()=>$('.sidebar').classList.toggle('open'),close:()=>$('#dialog').close(),cycle:()=>command({type:'cycle'},'Operating cycle completed. Evidence and decision queue refreshed.'),
 'customer.overview':e=>{const id=e.dataset.id,c=state.records.customers.find(x=>x.id===id),linked=Object.entries(state.records).flatMap(([k,rs])=>rs.filter(r=>r.customer===id).map(r=>({k,r})));modal(esc(c.name)+' · Account overview',`<div class="flex between">${badge(c.status)}<b>Health ${c.health}/100</b></div><p class="subsection">${esc(c.notes)}</p>${linked.map(({k,r})=>`<div class="metric-line"><div>${esc(r.name)}<br><small>${kinds[k].label} · ${esc(r.status)}</small></div>${btn('Open','record.open',`data-kind="${k}" data-id="${r.id}"`)}</div>`).join('')||'<p>No linked business records.</p>'}`);},
 'payment.open':e=>{const r=state.records.invoices.find(x=>x.id===e.dataset.id);modal('Record received payment',`<form id="payment-form" data-id="${r.id}"><p>${esc(r.name)} · Outstanding ${money(r.amount-r.paid)}</p><p class="muted">Record money already received. This updates the invoice balance and company cash; it does not initiate a bank transaction.</p>${field('amount','Amount received','money',r.amount-r.paid)}${field('reference','Unique bank or receipt reference','text')}${formEnd('Record payment')}</form>`);},
 'convert.open':e=>{const r=state.records.deals.find(x=>x.id===e.dataset.id);modal('Win deal & start delivery',`<form id="convert-form" data-id="${r.id}"><p>${esc(r.name)} · ${money(r.amount)}</p><p>Create a linked delivery project and optional deposit invoice. The invoice remains internal until you send it through your accounting process.</p>${field('deposit','Deposit invoice (% of deal value)','percent',25)}${field('due','Delivery deadline','date',dayAdd(today(),45))}${formEnd('Create delivery handoff')}</form>`);},
 'record.open':e=>openRecord(e.dataset.kind,e.dataset.id),'task.open':e=>openTask(e.dataset.id),'decision.open':e=>openDecision(e.dataset.id),
 'decision.approve':async e=>{await command({type:'decision.approve',id:e.dataset.id},'Decision approved. Assign the execution task next.');openDecision(e.dataset.id);},
 'decision.execute':async e=>{await command({type:'decision.execute',id:e.dataset.id},'Internal task assigned. No external action was sent.');openDecision(e.dataset.id);},
 'decision.reopen':async e=>{await command({type:'decision.reopen',id:e.dataset.id},'Decision reopened for fresh approval.');openDecision(e.dataset.id);},
 'decision.reject.open':e=>modal('Reject decision',`<form id="reject-form" data-id="${e.dataset.id}">${field('reason','Reason for rejecting','textarea')}${formEnd('Reject decision')}`),
 'decision.modify.open':e=>{const d=state.decisions.find(x=>x.id===e.dataset.id);modal('Modify recommended action',`<form id="modify-form" data-id="${d.id}">${field('action','Action','textarea',d.action)}${field('owner','Owner','text',d.owner)}${formEnd('Save revision')}`);},
 'decision.verify.open':e=>modal('Verify the outcome',`<form id="verify-form" data-id="${e.dataset.id}"><p>Record the observed result and its reference. This is a user-attested outcome; OPERON has not reconciled it against a bank or external system.</p>${field('category','Outcome type',['operational','cash_received','cost_saved','revenue_won'],'operational')}${field('amount','Observed amount (0 for operational result)','money',0)}${field('evidence','Evidence, source reference, and observed result','textarea')}${formEnd('Record verified outcome')}`),
 'record.remove':e=>modal('Archive record?',`<p>This removes the record from active work and keeps a recoverable copy in Administration. Linked records and unresolved decisions block archiving.</p><div class="dialog-foot">${btn('Cancel','close')}${btn('Remove record','record.remove.confirm',`data-kind="${e.dataset.kind}" data-id="${e.dataset.id}"`,'danger')}</div><p id="form-error" class="error"></p>`),
 'record.remove.confirm':async e=>{await command({type:'record.archive',kind:e.dataset.kind,id:e.dataset.id},'Record archived. Restore it from Administration.');$('#dialog').close();},
 'records.export':e=>{const k=e.dataset.kind;download('operon-'+k+'.csv',csv(state.records[k],['id',...Object.keys(kinds[k].fields)]),'text/csv');},
 'audit.export':()=>download('operon-audit.csv',csv(state.audit,['at','actor','action','entity','detail']),'text/csv'),
 backup:()=>download('operon-workspace-'+today()+'.json',JSON.stringify({format:'operon-backup-v1',exportedAt:new Date().toISOString(),state},null,2)),
 template:e=>{const k=e.dataset.kind,example=seedState().records[k][0];download(k+'-template.csv',csv([{...example,...('customer'in example?{customer:''}:{})}],Object.keys(kinds[k].fields)),'text/csv');},
 'import.open':e=>importOpen(e.dataset.kind),
 'workspace.open':()=>modal('Create workspace',`<form id="workspace-form">${field('name','Workspace name','text')}<label class="flex"><input type="checkbox" name="demo"> Load synthetic demonstration records</label>${formEnd('Create workspace')}`),
 'workspace.switch':()=>modal('Switch workspace',`${workspaces.map(w=>`<div class="metric-line"><span>${esc(w.name)}</span>${btn(w.id===workspaceId?'Current':'Open','workspace.select',`data-id="${w.id}"`)}</div>`).join('')}<div class="subsection">${btn('+ Create workspace','workspace.open')}</div>`),
 'workspace.select':async e=>{workspaceId=e.dataset.id;if(mode==='server')await loadWorkspace();else{state=JSON.parse(localStorage.getItem('operon.v2.workspaces'))[workspaceId];storeSandbox();}$('#dialog').close();navigate('overview');},
 'sandbox.info':()=>modal('About the interactive sandbox',`<p>This version uses synthetic company data and browser storage so you can exercise complete workflows at the existing GitHub Pages address.</p><p>The repository also includes a persistent server with accounts, workspace isolation, roles, invitations, and scheduled detection. GitHub Pages cannot run that server.</p><p>No external integrations, automated payments, paid subscriptions, or AI model are connected. Recommendations are explainable business rules.</p>${btn('Close','close','','primary')}`),
 'restore.open':()=>modal('Restore a workspace backup',`<p>Restore creates a separate workspace and leaves your current workspace intact. Import only a backup you trust.</p><form id="restore-form"><input type="file" id="backup-file" accept=".json" required>${formEnd('Restore as new workspace')}</form>`),
 'auth.toggle':()=>{authMode=authMode==='login'?'register':'login';authView();},logout:async()=>{await api('/logout',{});authView();},
 'invite.open':()=>modal('Create invitation',`<form id="invite-form">${field('email','Recipient email','email')}${field('role','Workspace role',['manager','operator','viewer'],'viewer')}${formEnd('Create invitation token')}`),
 'invite.accept.open':()=>modal('Accept invitation',`<form id="accept-form">${field('token','Invitation token','text')}${formEnd('Accept invitation')}`),
 'password.open':()=>modal('Change password',`<form id="password-form">${field('current','Current password','password')}${field('password','New password (12+ characters)','password')}${formEnd('Change password')}`),
 'member.open':e=>modal('Manage member',`<form id="member-form" data-id="${e.dataset.id}">${field('role','Role',['manager','operator','viewer'],e.dataset.role)}<label class="flex"><input name="remove" type="checkbox"> Remove workspace access</label>${formEnd('Update membership')}`)
};
document.addEventListener('click',async event=>{const e=event.target.closest('[data-action]');if(!e)return;event.preventDefault();try{e.disabled=true;await actions[e.dataset.action]?.(e);}catch(error){if($('#dialog').open&&$('#form-error'))$('#form-error').textContent=error.message;else toast(error.message);}finally{e.disabled=false;}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role=button]')){e.preventDefault();e.target.click();}});
document.addEventListener('change',e=>{if(e.target.id==='status-filter'){filter=e.target.value;pageNumber=1;render();}});
let searchTimer;document.addEventListener('input',e=>{
 if(e.target.id==='filter-search'){const pos=e.target.selectionStart;query=e.target.value;pageNumber=1;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{render();const f=$('#filter-search');f?.focus();f?.setSelectionRange(pos,pos);},180);}
 if(e.target.closest('#scenario-form')){const f=Object.fromEntries(new FormData($('#scenario-form')));for(const [k,v] of Object.entries(f))$('#'+k+'-value').textContent=v+'%';$('#scenario-result').innerHTML=scenarioResult(forecast(state,f));}
});
document.addEventListener('keydown',e=>{if(e.target.id==='global-search'&&e.key==='Enter'){const q=e.target.value.toLowerCase();const found=Object.entries(state.records).flatMap(([k,rs])=>rs.filter(r=>`${r.name} ${r.owner} ${r.notes}`.toLowerCase().includes(q)).map(r=>({k,r}))).slice(0,30);modal('Search results',found.length?found.map(({k,r})=>`<div class="metric-line"><span>${esc(r.name)}<br><small>${kinds[k].label}</small></span>${btn('Open','record.open',`data-kind="${k}" data-id="${r.id}"`)}</div>`).join(''):'<p>No matching records.</p>');}});
document.addEventListener('submit',async e=>{
 e.preventDefault();const form=e.target,b=Object.fromEntries(new FormData(form)),submit=form.querySelector('[type=submit]');if(submit?.disabled)return;if(submit)submit.disabled=true;
 try{
  if(form.id==='auth-form'){const d=await api(authMode==='login'?'/login':'/register',b);csrf=d.csrf;const u=await api('/me');me={name:u.name};workspaces=u.workspaces;workspaceId=workspaces[0].id;await loadWorkspace();render();return;}
  if(form.id==='payment-form')await command({type:'invoice.payment',id:form.dataset.id,...b},'Payment recorded and invoice balance updated');
  if(form.id==='convert-form')await command({type:'deal.convert',id:form.dataset.id,...b},'Deal won; linked project and deposit invoice created');
  if(form.id==='record-form')await command({type:'record.save',kind:form.dataset.kind,record:{...b,...(form.dataset.id?{id:form.dataset.id}:{})}});
  if(form.id==='task-form')await command({type:'task.save',task:{...b,...(form.dataset.id?{id:form.dataset.id}:{})}});
  if(form.id==='reject-form')await command({type:'decision.reject',id:form.dataset.id,reason:b.reason},'Decision rejected with reason');
  if(form.id==='modify-form')await command({type:'decision.modify',id:form.dataset.id,action:b.action,owner:b.owner},'Decision revised');
  if(form.id==='verify-form')await command({type:'decision.verify',id:form.dataset.id,...b},'Evidence and outcome recorded');
  if(form.id==='permissions-form'){const permissions={manager:[],operator:[]};for(const key of Object.keys(b)){const [role,cap]=key.split('|');if(permissions[role])permissions[role].push(cap);}await command({type:'policy.save',permissions},'Authorization matrix saved and enforced');return;}
  if(form.id==='settings-form'){await command({type:'settings',company:{...b,automation:b.automation==='on'}},'Company settings saved');return;}
  if(form.id==='import-form'){const file=$('#csv-file').files[0];if(!file||file.size>2000000)throw Error('Choose a CSV file smaller than 2 MB');const rows=parseCSV(await file.text());rows.forEach((r,i)=>{try{validateRecord(form.dataset.kind,r,state);}catch(err){throw Error('Row '+(i+2)+': '+err.message);}});await command({type:'import',kind:form.dataset.kind,rows},rows.length+' validated records imported');}
  if(form.id==='workspace-form'){if(mode==='server'){const d=await api('/workspaces',{name:b.name,demo:b.demo==='on'});workspaces=d.workspaces;workspaceId=d.id;await loadWorkspace();}else{workspaceId=crypto.randomUUID();state=b.demo==='on'?seedState():emptyState(b.name);state.company.name=b.name;storeSandbox();}navigate('overview');}
  if(form.id==='restore-form'){const file=$('#backup-file').files[0];if(!file||file.size>10000000)throw Error('Choose a backup smaller than 10 MB');const backup=JSON.parse(await file.text());const restored=restoreBackup(backup);workspaceId=crypto.randomUUID();state=restored;state.company.name+=' (restored)';storeSandbox();navigate('overview');}
  if(form.id==='invite-form'){const d=await api('/workspaces/'+workspaceId+'/invites',b);await loadWorkspace();modal('Invitation created',`<p>Share this token with <b>${esc(b.email)}</b>. They must sign in using that email and choose “Accept invitation” under Team & access. Expires in seven days. No email was sent.</p><div class="integration-code">${esc(d.token)}</div>`);return;}
  if(form.id==='accept-form'){const d=await api('/invites/accept',b);workspaces=d.workspaces;toast('Invitation accepted. Use the workspace switcher to open it.');}
  if(form.id==='password-form'){await api('/password',b);toast('Password changed. Other sessions were signed out.');}
  if(form.id==='member-form'){await api('/workspaces/'+workspaceId+'/members',{user:form.dataset.id,role:b.role,remove:b.remove==='on'});await loadWorkspace();render();toast('Membership updated');}
  $('#dialog').close();
 }catch(error){const target=form.querySelector('#form-error');if(target)target.textContent=error.message;else toast(error.message);}finally{if(submit)submit.disabled=false;}
});
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'overview';query='';filter='';pageNumber=1;if(state)render();});
async function start(){
 const staticHost=location.hostname.endsWith('github.io')||new URLSearchParams(location.search).has('sandbox');
 if(!staticHost){try{const health=await fetch('/api/health');if(health.ok&&(await health.json()).version){mode='server';try{const u=await api('/me');csrf=u.csrf;me={name:u.name};workspaces=u.workspaces;workspaceId=workspaces.find(w=>w.id===sessionStorage.getItem('operon.workspace'))?.id||workspaces[0].id;await loadWorkspace();render();}catch(e){if(e.status===401)authView();else throw e;}return;}}catch(e){$('#app').innerHTML=empty('Could not reach your workspace','The server is unavailable. Your saved server data has not been replaced with sample data. Reload to retry.');return;}}
 try{const all=JSON.parse(localStorage.getItem('operon.v2.workspaces')||'{}');workspaceId=localStorage.getItem('operon.v2.selected');if(!all[workspaceId]){workspaceId='demo';state=seedState();}else state=all[workspaceId];storeSandbox();render();}catch(e){$('#app').innerHTML=empty('Browser storage unavailable','Enable browser storage or use the OPERON server. No data has been overwritten.');}
}
setInterval(async()=>{if(mode==='sandbox'&&state?.company.automation&&!busy&&(!state.lastCycle||Date.now()-Date.parse(state.lastCycle)>state.company.cycleMinutes*60000))try{await command({type:'cycle'},'Scheduled operating cycle completed');}catch(e){toast(e.message);}},30000);
function productivityView(){const p=productivity(state),max=Math.max(...p.stages.map(x=>x.count),1),moneyMax=Math.max(...p.aging,1);return head('Performance & productivity','Find waiting work, overdue commitments, and the next operational bottleneck.',btn('Review pending decisions','navigate','data-route="decisions"','primary'))+`<div class="grid kpis">${kpi('Overdue work',p.overdue,'Open tasks past their due date')}${kpi('Completed in 7 days',p.completed7,'Distinct tasks with completion events')}${kpi('Median decision cycle',p.medianCycleHours===null?'No sample':p.medianCycleHours.toFixed(1)+'h',p.cycleSample+' verified decisions with timestamps')}${kpi('Unassigned work',p.unassigned,'Open tasks without a responsible owner')}</div><div class="grid two-col"><section class="card"><h2>Where decisions are waiting</h2><p class="muted">Oldest pending decision: ${p.waiting?p.oldestWaitHours.toFixed(1)+' hours':'none'}. These are measured workspace timestamps.</p>${p.stages.map(x=>`<div class="funnel-row"><span>${esc(x.status.replaceAll('_',' '))}</span><div class="mini-bar"><span style="width:${x.count/max*100}%"></span></div><b>${x.count}</b></div>`).join('')}<div class="detail-block"><b>Next improvement</b><p>${p.blocked?'Resolve '+p.blocked+' blocked tasks before assigning more work.':p.overdue?'Review '+p.overdue+' overdue commitments and confirm realistic deadlines.':p.waiting?'Triage the pending queue; approve and assign the ready decisions together.':'Add business records and run a cycle to establish your baseline.'}</p></div></section><section class="card"><h2>Receivables aging</h2>${['1–7 days','8–30 days','31–60 days','Over 60 days'].map((l,i)=>`<div class="health-row"><div class="flex between"><span>${l}</span><b>${money(p.aging[i])}</b></div><div class="mini-bar"><span style="width:${p.aging[i]/moneyMax*100}%"></span></div></div>`).join('')}${btn('Open receivables','navigate','data-route="invoices"','text-btn')}</section></div><section class="card subsection"><h2>Ownership and workload</h2>${p.owners.length?`<div class="table-wrap"><table><thead><tr><th>Owner</th><th>Open tasks</th><th>Overdue</th></tr></thead><tbody>${p.owners.map(o=>`<tr><td>${esc(o.owner)}</td><td>${o.open}</td><td>${o.overdue}</td></tr>`).join('')}</tbody></table></div>`:empty('No assigned work yet','Approve and assign a decision to start measuring execution workload.')}<p class="muted subsection">Task counts do not measure individual employee performance. Work complexity and available hours are not included.</p></section>`;}
function permissionsView(){return head('Authorization matrix','One policy shared by the interface and server. All members can read workspace records.')+`<div class="notice">Owner authority and the read-only viewer role are fixed. Only the owner can edit Manager and Operator capabilities. Financial-exposure approvals above ${money(state.company.approvalLimit)} still require the owner.</div><form id="permissions-form"><div class="table-wrap"><table><thead><tr><th>Capability</th>${['owner','manager','operator','viewer'].map(r=>`<th>${label(r)}</th>`).join('')}</tr></thead><tbody>${Object.entries(capabilities).map(([cap,l])=>`<tr><td>${l}<div class="cell-sub">${cap}</div></td>${['owner','manager','operator','viewer'].map(role=>`<td><input type="checkbox" aria-label="${label(role)}: ${l}" name="${role}|${cap}" ${can(state,role,cap)?'checked':''} ${me.role!=='owner'||['owner','viewer'].includes(role)||['policy.manage','members.manage'].includes(cap)?'disabled':''}></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="toolbar subsection"><small>Policy edits are recorded in the workspace audit trail.</small><button type="submit" class="primary" ${me.role!=='owner'?'disabled':''}>Save authorization matrix</button></div><p id="form-error" class="error" role="alert"></p></form>`;}
function adminView(){if(me.role!=='owner')return head('Administration','Workspace administration is restricted to the owner.')+empty('Owner access required','You can review your effective permissions in the authorization matrix.',btn('View authorization matrix','navigate','data-route="permissions"'));const p=productivity(state),count=Object.values(state.records).reduce((a,r)=>a+r.length,0);return head('Admin control panel','Workspace health, access, operating policies, and recovery.',btn('Authorization matrix','navigate','data-route="permissions"','primary'))+`<div class="grid kpis">${kpi('Business records',count,'Across seven operating domains')}${kpi('Pending approvals',p.waiting,'Subject to role and financial authority')}${kpi('Recoverable records',(state.trash||[]).length,'Archived records retained for restoration')}${kpi('Scheduled detection',state.company.automation?'Enabled':'Paused',mode==='server'?'While the persistent server is running':'Only while this sandbox is open')}</div><div class="grid three-col"><section class="card"><h2>Access & policy</h2><p class="muted">Assign roles, revoke invitations, and control approval authority.</p><div class="flex wrap">${btn('Manage team','navigate','data-route="team"')}${btn('Edit matrix','navigate','data-route="permissions"')}</div></section><section class="card"><h2>Operating controls</h2><p class="muted">Set the cash baseline, approval limit, and detection schedule.</p>${btn('Company settings','navigate','data-route="settings"')}</section><section class="card"><h2>Evidence & recovery</h2><p class="muted">Export the audit history and restore accidentally archived records.</p>${btn('Export audit','audit.export')}${btn('Export backup','backup')}</section></div><div class="grid two-col subsection"><section class="card"><h2>Runtime security</h2><div id="admin-runtime">${mode==='sandbox'?'<p class="muted">Browser sandbox. Server sessions, authentication, and secure cookies do not run on GitHub Pages.</p>':'<p>Loading server configuration…</p>'}</div><div class="metric-line"><span>Authorization</span><b>${mode==='server'?'Server enforced':'Local demonstration'}</b></div><div class="metric-line"><span>MFA / email recovery</span><b>Not configured</b></div><div class="metric-line"><span>External integrations / billing</span><b>Not connected</b></div></section><section class="card"><h2>Pending invitations</h2><div id="admin-invites">${mode==='server'?'Loading invitations…':'Available in the server workspace.'}</div></section></div><section class="card subsection"><h2>Recovery center</h2>${(state.trash||[]).map(t=>`<div class="metric-line"><div>${esc(t.record.name)}<br><small>${esc(kinds[t.kind]?.label)} · ${time(t.at)}</small></div>${btn('Restore','archive.restore',`data-id="${esc(t.id)}"`)}</div>`).join('')||'<p class="muted">No archived records. Future removals can be restored here.</p>'}</section><section class="card subsection"><h2>Scheduled jobs</h2><div id="admin-jobs">${mode==='server'?'Loading recent runs…':'Sandbox cycles are recorded in Outcomes & memory.'}</div></section>`;}
async function loadAdmin(){if(mode!=='server'||me.role!=='owner')return;try{const d=await api('/workspaces/'+workspaceId+'/admin');if(!$('#admin-runtime'))return;$('#admin-runtime').innerHTML=`<div class="metric-line"><span>Secure cookies / HTTPS policy</span><b>${d.secureCookies?'Enabled':'Not enabled — local development'}</b></div><div class="metric-line"><span>Public registration</span><b>${d.signupOpen?'Open':'Closed'}</b></div>`;$('#admin-invites').innerHTML=d.invites.map(i=>`<div class="metric-line"><div>${esc(i.email)}<br><small>${esc(i.role)} · Expires ${new Date(i.expires).toLocaleDateString()}</small></div>${btn('Revoke','invite.revoke',`data-id="${i.id}"`)}</div>`).join('')||'<p class="muted">No pending invitations.</p>';$('#admin-jobs').innerHTML=d.jobs.map(j=>`<div class="metric-line"><span>${time(j.started)}</span>${badge(j.status)}<small>${esc(j.error||'')}</small></div>`).join('')||'<p class="muted">No scheduled runs yet. Enable the schedule in Settings.</p>';}catch(e){if($('#admin-runtime'))$('#admin-runtime').textContent=e.message;}}
async function loadSessions(){if(mode!=='server')return;try{const d=await api('/sessions');if($('#session-list'))$('#session-list').innerHTML=d.sessions.map(s=>`<div class="metric-line"><div>${s.current?'This session':'Other session'}<br><small>${esc(s.agent||'Unknown client').slice(0,90)}<br>Last active ${s.lastSeen?time(s.lastSeen):'Unknown'}</small></div>${s.current?badge('active'):btn('Sign out','session.revoke',`data-id="${s.id}"`)}</div>`).join('');}catch(e){toast(e.message);}}
function applyUIAuthorizations(){const map={'record.open':'records.write','record.remove':'records.delete','import.open':'data.import','cycle':'cycles.run','decision.approve':'decisions.approve','decision.approve_assign':'decisions.approve','decision.reject.open':'decisions.approve','decision.modify.open':'decisions.approve','decision.execute':'decisions.execute','task.open':'tasks.write','task.complete':'tasks.write','decision.verify.open':'outcomes.verify','payment.open':'finance.record','convert.open':'sales.convert','invite.open':'members.manage'};document.querySelectorAll('[data-action]').forEach(el=>{const cap=map[el.dataset.action];if(cap&&!can(state,me.role,cap)&&!(['record.open','task.open'].includes(el.dataset.action)&&el.dataset.id)){el.disabled=true;el.title='Your role does not allow: '+capabilities[cap];}});for(const [form,cap] of [['#record-form','records.write'],['#task-form','tasks.write']])if(!can(state,me.role,cap))document.querySelectorAll(form+' input,'+form+' textarea,'+form+' select,'+form+' button[type=submit]').forEach(e=>e.disabled=true);if(route==='settings'&&!can(state,me.role,'policy.manage'))document.querySelectorAll('#settings-form input,#settings-form button').forEach(e=>e.disabled=true);}
Object.assign(actions,{
 'page':e=>{pageNumber=Math.max(1,Number(e.dataset.page));render();window.scrollTo(0,0);},
 'decision.approve_assign':async e=>{await command({type:'decision.approve_assign',id:e.dataset.id},'Approved and assigned. Open Execution board to track the work.');},
 'task.complete':async e=>{const t=state.tasks.find(x=>x.id===e.dataset.id);await command({type:'task.save',task:{...t,status:'completed'}},'Task completed. Record outcome evidence next.');},
 'task.filter':e=>{filter=e.dataset.filter;render();},
 'archive.restore':e=>command({type:'record.restore',id:e.dataset.id},'Archived record restored'),
 'invite.revoke':async e=>{await api('/workspaces/'+workspaceId+'/invite-revoke',{id:e.dataset.id});await loadWorkspace();render();toast('Invitation revoked');},
 'session.revoke':async e=>{await api('/sessions/revoke',{id:e.dataset.id});await loadSessions();toast('Other session signed out');},
 'sessions.others':async()=>{await api('/sessions/revoke',{others:true});await loadSessions();toast('Other sessions signed out');}
});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search')?.focus();}if(e.key==='Escape')$('.sidebar')?.classList.remove('open');});

start();
